import{_ as e,a as o}from"./chunks/users.zh.D25tYuV-.js";import{_ as a}from"./chunks/settings.zh.BbiDo0sw.js";import{_ as r,c as i,o as d,ae as l}from"./chunks/framework.BnYZi0O_.js";const n="/xiaozhi-mcphub/assets/register.CN486xXs.png",q=JSON.parse('{"title":"认证与多账户","description":"","frontmatter":{},"headers":[],"relativePath":"features/authentication.md","filePath":"features/authentication.md"}'),s={name:"features/authentication.md"};function c(h,t,u,p,m,b){return d(),i("div",null,t[0]||(t[0]=[l('<h1 id="认证与多账户" tabindex="-1">认证与多账户 <a class="header-anchor" href="#认证与多账户" aria-label="Permalink to &quot;认证与多账户&quot;">​</a></h1><p>xiaozhi-mcphub <strong>1.1.0</strong> 在 JWT 控制台登录之外，支持注册、邮箱验证、找回密码，以及按 <strong>owner</strong> 隔离的 Server / Group / 小智端点数据。</p><p><img src="'+e+'" alt="登录"></p><h2 id="登录与注册" tabindex="-1">登录与注册 <a class="header-anchor" href="#登录与注册" aria-label="Permalink to &quot;登录与注册&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>登录</td><td>用户名 + 密码；可选「记住账号」</td></tr><tr><td>注册</td><td><code>/register</code>；若启用邮件服务，可能要求邮箱并验证后才能登录</td></tr><tr><td>找回密码</td><td>邮件服务启用时可用；重置链接打开「设置新密码」</td></tr><tr><td>社交登录</td><td>可选 Better Auth（GitHub / Google / OIDC），需 DB</td></tr></tbody></table><p><img src="'+n+'" alt="注册"></p><h3 id="密码强度" tabindex="-1">密码强度 <a class="header-anchor" href="#密码强度" aria-label="Permalink to &quot;密码强度&quot;">​</a></h3><p>前后端统一规则（稳定错误码 + i18n）：</p><ul><li>至少 <strong>8</strong> 位</li><li>至少一个字母、一个数字、一个特殊字符</li></ul><p>中文界面会显示「密码不符合安全要求」等本地化文案，而不是英文原文。</p><h3 id="默认管理员" tabindex="-1">默认管理员 <a class="header-anchor" href="#默认管理员" aria-label="Permalink to &quot;默认管理员&quot;">​</a></h3><ul><li>本地 <code>pnpm dev</code>：常见 <code>admin</code> / <code>admin123</code>（请尽快修改）</li><li>其它启动：可用 <code>ADMIN_PASSWORD</code> 仅在<strong>首次空用户表</strong>时生效；否则看启动日志中的随机密码</li></ul><h2 id="角色与权限" tabindex="-1">角色与权限 <a class="header-anchor" href="#角色与权限" aria-label="Permalink to &quot;角色与权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>典型能力</th></tr></thead><tbody><tr><td>管理员 <code>isAdmin</code></td><td>所有 Server/Group/端点、用户管理、系统日志流、实例级 <code>dbUrl</code>、全局诊断</td></tr><tr><td>普通用户</td><td>仅自己的资源；设置里可改个人集成（如 ModelScope / MCPRouter）；不可越权管理他人「公开」服务器的配置</td></tr></tbody></table><p>前端权限点包括 <code>settings:smart_routing</code>、<code>settings:user_integrations</code> 等。</p><h2 id="数据隔离-1-1-0" tabindex="-1">数据隔离（1.1.0） <a class="header-anchor" href="#数据隔离-1-1-0" aria-label="Permalink to &quot;数据隔离（1.1.0）&quot;">​</a></h2><ul><li><strong>Server / Group</strong> 唯一键为 <strong><code>(owner, name)</code></strong>，不同用户可同名</li><li>JSON 存储键形如 <code>owner::name</code>；遗留无 owner 资源启动时会回填为 <code>admin</code></li><li>列表接口按当前用户过滤；管理 API 优先 <code>findByOwnerAndName</code></li><li><strong>活动日志</strong>强制用户作用域；<strong>系统日志 SSE</strong> 仅管理员（前端有限重试，避免 403 刷屏）</li><li>小智端点按 owner 可见；「服务启用」由当前用户端点聚合，不再使用实例总开关挡连接</li></ul><h2 id="每用户配置" tabindex="-1">每用户配置 <a class="header-anchor" href="#每用户配置" aria-label="Permalink to &quot;每用户配置&quot;">​</a></h2><p>系统级仍放在 <code>SystemConfig</code>（DB URL、Better Auth、安装 baseUrl 等）。<br> 用户可覆盖的个人项包括（见 <code>UserConfig</code>）：</p><ul><li><code>smartRouting</code>（<strong>不可</strong>覆盖系统 <code>dbUrl</code>）</li><li><code>toolResultCompression</code></li><li><code>mcpRouter</code> / <code>modelscope</code> API 相关字段</li></ul><p>运行时通过 <code>effectiveConfig</code> 做 system + user 合并。</p><h2 id="邮件" tabindex="-1">邮件 <a class="header-anchor" href="#邮件" aria-label="Permalink to &quot;邮件&quot;">​</a></h2><p>在 <strong>设置</strong> 中配置 SMTP（主机、端口、账号、发件人等）。启用后：</p><ul><li>注册验证邮件</li><li>密码重置邮件</li><li>可发测试邮件</li></ul><p>未配置邮件时，注册可仍可用（视部署策略），但验证/找回不可用。</p><h2 id="better-auth" tabindex="-1">Better Auth <a class="header-anchor" href="#better-auth" aria-label="Permalink to &quot;Better Auth&quot;">​</a></h2><p>见 <a href="/xiaozhi-mcphub/configuration/environment-variables.html">环境变量 · Better Auth</a>。要点：</p><ol><li>必须 <code>DB_URL</code></li><li>配置客户端密钥与 <code>BETTER_AUTH_URL</code></li><li>改环境变量后需<strong>重启</strong>进程</li></ol><h2 id="相关界面" tabindex="-1">相关界面 <a class="header-anchor" href="#相关界面" aria-label="Permalink to &quot;相关界面&quot;">​</a></h2><p><img src="'+o+'" alt="用户管理"></p><p><img src="'+a+'" alt="设置"></p>',31)]))}const x=r(s,[["render",c]]);export{q as __pageData,x as default};
